using Framework.Configs;
using Framework.Entities.Roles.Controllers;
using Framework.Entities.StatsModule;
using Framework.Games;
using Framework.Misc.Debugs;
using Framework.Misc.Tools;
using HutongGames.PlayMaker;
using UnityEngine;

namespace Scripts.PlayMakers
{
    [Title("Flee")]
    public class FleeFsmAction : RoleControllerAIState
    {
        [Title("Retreat Target")] public FsmGameObject target;
        [Title("Retreat Succeeded")] public FsmEvent successEvt;
        [Title("Retreat Failed (Timeout)")] public FsmEvent failEvt;

        //Calculate from the current position.
        [Title("Retreat Distance (Relative)")] public FsmFloat distance = 2;

        //Check whether the retreat destination has been reached.
        [Title("Arrival Threshold")] public FsmFloat minCheckDistance = 0.05f;

        [Title("Maximum Retreat Time")] public FsmFloat maxTime = 2;

        [Title("Retreat Speed Scale")] public FsmFloat moveSpeedScale;
        [Title("Lerp")] public FsmFloat lerpDelta = 0.05f;

        private RoleController _targetRole;

        private float _curTime;

        private StatModifier _statModifier;

        public override void OnEnter()
        {
            // The team's base class gets the role component from the FSM owner.
            base.OnEnter();
            if (target.Value)
            {
                // Unity GetComponent retrieves the target's RoleController.
                _targetRole = target.Value.GetComponent<RoleController>();
            }

            if (!_targetRole)
            {
                Finish();
                return;
            }

            _curTime = 0;
            // The team's coordinate API reads world positions; IgnoreY sets Y to zero for XZ-plane calculations.
            var tp = _targetRole.worldPosition.IgnoreY();
            var cp = role.worldPosition.IgnoreY();

            // Unity normalized gives the direction to the target; extend it backward by distance to find the retreat point.
            // Calculate the destination only on entry; keep it fixed during updates.
            _targetPosition = cp - (tp - cp).normalized * distance.Value;
            // Team debug API: ToView maps (x, y, z) to (x, y + z, z).
            // DrawPoint draws a marker only in the editor.
            PostDrawGizmos.DrawPoint(_targetPosition.ToView());

            if (moveSpeedScale.Value > 0)
            {
                // Team stat system: FinalMultiply uses a final multiplier of (1 + the sum of modifiers).
                _statModifier = new StatModifier(moveSpeedScale.Value, ModifierParamTypeEnum.FinalMultiply);
                role.stats.AddModifier(StatConst.moveSpeed, _statModifier);
            }
        }

        public override void OnExit()
        {
            base.OnExit();
            // The team's Move method toggles the movement flag; the controller handles animation and speed.
            role.Move(false);
            if (_statModifier != null)
            {
                // Remove only the speed modifier added by this action.
                role.stats.RemoveModifier(StatConst.moveSpeed, _statModifier);
                _statModifier = null;
            }
        }

        private float _delta;
        private float _randomInterval;
        private Vector3 _targetPosition;

        public override void OnUpdate()
        {
            base.OnUpdate();

            // PlayMaker: Fsm.Event sends an event; Finish marks the action complete.
            if (_targetRole == null || _targetRole.isDead)
            {
                Fsm.Event(failEvt);
                Finish();
                return;
            }

            if (maxTime.Value > 0)
            {
                if (_curTime < maxTime.Value)
                {
                    // The team's Game.deltaTime normally uses Unity Time.deltaTime; it is zero while scripts are paused.
                    _curTime += Game.deltaTime;
                }
                else
                {
                    Fsm.Event(failEvt);
                    Finish();
                    return;
                }
            }

            var cp = role.worldPosition.IgnoreY();

            if (Vector3.Distance(_targetPosition, cp) <= minCheckDistance.Value)
            {
                Fsm.Event(successEvt);
                Finish();
            }
            else
            {
                var dir = (_targetPosition - cp).normalized;
                // The team's API checks the role bounds against the Wall layer and scores eight directions, penalizing blocked ones.
                // Returns the highest-scoring local direction, not a full path.
                dir = GameTools.PathFinderEightDirectionXZFromPosition(role.entityTransform.worldBounds, dir);
                // Unity Lerp smooths the direction by lerpDelta each update; this factor is not scaled by frame time.
                dir = Vector3.Lerp(role.operationDirection, dir, lerpDelta.Value);
                // The team's API checks direction-control permissions, then writes the direction and updates facing.
                role.SetOperationDirection(dir);
                if (!role.isMoveing)
                    role.Move(true);
            }
        }
    }
}

