using System;
using System.Globalization;
using Framework.Entities.Buffs;
using Framework.Entities.Roles.Components;
using Framework.Games;
using Sirenix.OdinInspector;
using UnityEngine;
using Utilities;

namespace Scripts.BuffModules
{
    /// <summary>Expire the buff after a number of monster kills rather than elapsed time.</summary>
    [Serializable]
    [Name("General/Kill Count Lifetime")]
    public class KillCountModule : BuffModule
    {
        [LabelText("Kills Until Expiry")] [Min(1)] [SerializeField]
        private int _killLimit = 3;

        // This runtime counter is not saved in the buff configuration.
        [NonSerialized] private KillCountLifetime _lifetime;

        public int remainingKills
        {
            get
            {
                if (_lifetime != null)
                {
                    return _lifetime.remainingKills;
                }

                return Math.Max(1, _killLimit);
            }
        }

        public override void OnStart()
        {
            // The team's Buff framework provides role; Game.dispatcher sends events, and buff.Destroy removes the expired buff.
            _lifetime = new KillCountLifetime(role, Game.dispatcher, _killLimit, buff.Destroy);
        }

        /// <summary>Reapplying the same buff refreshes the count without stacking its stat bonus.</summary>
        public override void OnStacking(Buff incoming)
        {
            var module = incoming.GetModule<KillCountModule>();
            if (module != null && _lifetime != null)
            {
                _lifetime.Refresh(module._killLimit);
            }
        }

        public override void OnEnd()
        {
            if (_lifetime != null)
            {
                _lifetime.Dispose();
            }

            _lifetime = null;
        }

        public override bool TryGetVariable(string varName, out string value)
        {
            if (varName == "buff_remaining_kills")
            {
                // Use a fixed numeric format for the project's expression system.
                value = remainingKills.ToString(CultureInfo.InvariantCulture);
                return true;
            }

            return base.TryGetVariable(varName, out value);
        }
    }
}
